args.source:
export default behaviour({
  name: 'PlayerHealth',
  params: { max: 100, dps: 20 },
  state: { hp: 100, on: false },
  inputs: ['enter', 'exit'],
  outputs: ['hp', 'died'],
  on: {
    enter() { if (!this.state.on) { this.state.on = true; this.after(0.25, 'tick'); } },
    exit() { this.state.on = false; }
  },
  tick() {
    if (!this.state.on) return;
    this.state.hp = Math.max(0, this.state.hp - this.params.dps * 0.25);
    if (this.state.hp <= 0) {
      this.state.hp = this.params.max;
      this.state.on = false;
      this.emit('died');
      return;
    }
    this.after(0.25, 'tick');
  }
});

