export default behaviour({
  name: 'LanternState',
  state: { lit1: false, lit2: false, lit3: false },
  inputs: ['click1', 'click2', 'click3'],
  outputs: ['lit1', 'lit2', 'lit3'],
  on: {
    click1() { this.state.lit1 = true; },
    click2() { this.state.lit2 = true; },
    click3() { this.state.lit3 = true; }
  }
});

